export type Tone = 'warm' | 'cool' | 'neutral';

export interface Fabric {
  id: string;
  name: string;
  tone: Tone;
  hex: string;
  material: string;
  pricePerMeter: number;
  description: string;
  colourName?: string;
  width?: string;
  care?: string;
}

export interface ToneInfo {
  key: Tone;
  label: string;
  desc: string;
  swatches: string[];
}

